-- Format the 600 Palace directions and Homura's relationship to Mikado.
SET AUTOCOMMIT FALSE;
CREATE LOCAL TEMPORARY TABLE REL_FORMAT_PEOPLE (
    REF VARCHAR(12) PRIMARY KEY, NAME VARCHAR(255) NOT NULL, WORLD VARCHAR(24) NOT NULL,
    AFFILIATION VARCHAR(120) NOT NULL
);
CREATE LOCAL TEMPORARY TABLE REL_FORMAT_RESOLVED (
    REF VARCHAR(12) PRIMARY KEY, CHARACTER_ID BIGINT UNIQUE NOT NULL
);
SELECT candidate.REF, c.ID
FROM REL_FORMAT_PEOPLE candidate JOIN ORIGINAL_CHARACTER c ON c.NAME=candidate.NAME
AND c.WORLD=candidate.WORLD AND COALESCE(c.AFFILIATION,'')=candidate.AFFILIATION;
CREATE LOCAL TEMPORARY TABLE REL_FORMAT_CHECK (
    MATCHED INTEGER CHECK (MATCHED=26)
);

CREATE LOCAL TEMPORARY TABLE REL_FORMAT_INPUT (
    SOURCE_REF VARCHAR(12), TARGET_REF VARCHAR(12), TITLE VARCHAR(60) NOT NULL,
    CALL_NAME VARCHAR(255) NOT NULL, ATTITUDE VARCHAR(2000) NOT NULL, SOCIAL VARCHAR(2000) NOT NULL,
    PRIOR_NOTE VARCHAR(2000) NOT NULL, PRIMARY KEY (SOURCE_REF,TARGET_REF)
);

CREATE LOCAL TEMPORARY TABLE REL_FORMAT_APPLY (
    SOURCE_ID BIGINT, TARGET_ID BIGINT, TITLE VARCHAR(60) NOT NULL, EXISTING_ID BIGINT,
    PREVIOUS_DESCRIPTION VARCHAR(2000) NOT NULL, PRIOR_NOTE VARCHAR(2000) NOT NULL,
    NEW_DETAIL VARCHAR(6000) NOT NULL, PRIMARY KEY (SOURCE_ID,TARGET_ID)
);
SELECT source_character.CHARACTER_ID, target_character.CHARACTER_ID, candidate.TITLE,
       existing.ID, COALESCE(existing.DESCRIPTION,''), candidate.PRIOR_NOTE,
       '【関係詳細】' || CHAR(10) || '呼び方：' ||
       COALESCE(
         REGEXP_SUBSTR(existing.DESCRIPTION, '呼び方（[^）]+）：([^\r\n]+)', 1, 1, '', 1),
         '「' || candidate.CALL_NAME || '」'
       ) || CHAR(10) || '接し方：' || candidate.ATTITUDE ||
       CHAR(10) || '具体的な付き合い：' || candidate.SOCIAL
FROM REL_FORMAT_INPUT candidate
JOIN REL_FORMAT_RESOLVED source_character ON source_character.REF=candidate.SOURCE_REF
JOIN REL_FORMAT_RESOLVED target_character ON target_character.REF=candidate.TARGET_REF
LEFT JOIN CHARACTER_RELATION existing ON existing.ID=(
    SELECT MIN(r.ID) FROM CHARACTER_RELATION r
    WHERE r.SOURCE_ID=source_character.CHARACTER_ID AND r.TARGET_ID=target_character.CHARACTER_ID
    AND (candidate.TARGET_REF<>'161' OR r.RELATION_TYPE=candidate.TITLE)
);

-- Remove the old structured block. Preserve locally added notes and wording outside that block.
CREATE LOCAL TEMPORARY TABLE REL_FORMAT_RESULT (
    SOURCE_ID BIGINT, TARGET_ID BIGINT, TITLE VARCHAR(60) NOT NULL, EXISTING_ID BIGINT,
    DETAIL VARCHAR(2000) NOT NULL, PRIMARY KEY (SOURCE_ID,TARGET_ID)
);
SELECT SOURCE_ID,TARGET_ID,TITLE,EXISTING_ID,
       NEW_DETAIL || CASE WHEN REMAINDER='' OR REMAINDER=PRIOR_NOTE THEN ''
                          ELSE CHAR(10) || CHAR(10) || REMAINDER END
FROM (
    SELECT candidate.*,
      REGEXP_REPLACE(
        REGEXP_REPLACE(PREVIOUS_DESCRIPTION,
          '【パレス関係詳細】\r?\n呼び方[^\r\n]*\r?\n接し方[^\r\n]*\r?\n関係[^\r\n]*\r?\n具体的な付き合い[^\r\n]*',''),
        '^\s+|\s+$','') AS REMAINDER
    FROM REL_FORMAT_APPLY candidate
    WHERE LOCATE('【関係詳細】', PREVIOUS_DESCRIPTION)=0
) draft;

UPDATE CHARACTER_RELATION existing
SET DESCRIPTION=(SELECT candidate.DETAIL FROM REL_FORMAT_RESULT candidate WHERE candidate.EXISTING_ID=existing.ID)
WHERE EXISTS (SELECT 1 FROM REL_FORMAT_RESULT candidate WHERE candidate.EXISTING_ID=existing.ID);
SELECT SOURCE_ID,TARGET_ID,TITLE,DETAIL FROM REL_FORMAT_RESULT WHERE EXISTING_ID IS NULL;
COMMIT;
