INSERT INTO REL_FORMAT_INPUT VALUES
    ('129', '130', '八星剣の同僚', 'スイ', '打ち解けているが、遠慮なく意見をぶつける。', 'ミカドの話になると張り合うこともある。人目のないところでは、互いの失敗談を笑って話せる。', '八星剣の幹部同士。'),
    ('129', '131', '八星剣の同僚', 'フウ', '豪快に笑い、年下の妹分のように扱う。', '休日に外へ誘われると、気が向けば競走に付き合う。勝敗よりもフウの勢いに乗って楽しむ仲。', '八星剣の幹部同士。'),
    ('129', '132', '八星剣の同僚', 'ライ', '気安く絡み、気だるい返事にも懲りない。', '夜にゲームを教わると負けず嫌いを発揮する。何戦も続けた末、食堂で夜食を取ることがある。', '八星剣の幹部同士。'),
    ('129', '133', '八星剣の同僚', 'チカ', '遠回しにせず、堅苦しい態度をからかう。', '早起きした休日は散歩に付き合うことがある。ミカドの前で固くなるチカを、あとで軽く茶化す。', '八星剣の幹部同士。'),
    ('129', '134', '八星剣の同僚', 'ユキ', '明るく声をかけ、返事が短くても気にしない。', 'ユキが動物を眺めていると、隣に腰を下ろして一緒に見る。静かなままで過ごせる仲。', '八星剣の幹部同士。'),
    ('129', '135', '八星剣の同僚', 'ヒカリ', '頼りにしており、心配されると少し照れながらも応じる。', 'ミカドのことで浮かれた日も落ち込んだ日も、ヒカリの茶に付き合うとつい本音が出る。', '八星剣の幹部同士。'),
    ('129', '136', '八星剣の同僚', 'ヤミ', '気安いが、ミカドのことでは譲らない。', '八星剣の仲間として付き合いは良好。ミカドの隣の席をどちらが取るかでは、静かに火花が散る。', '八星剣の幹部同士。'),
    ('129', '141', 'ミカドの妹・業務で会う相手', 'ミコト', '牽制を受けても動じず、軽口を返す。', 'ミカドと二人で出かける話が出るとよく張り合う。互いにミカドを大切にしていることは分かっている。', ''),
    ('129', '145', '部下・相談役', 'シュカ', '気安く遠慮が少ない。小言には軽口で返すが、意見は信用している。', '気を許せる相手。夜に二人で茶を飲み、段取りの話を離れてミカドのことでぼやくことがある。', 'よくお小言を言われる。副官なんだからもう少し敬えよ'),
    ('129', '146', '担当を通じて協力する同僚', 'セイラ', '面白がって話を聞くが、巻き込まれそうなら即座に断る。', '珍しい味の飲み物を勧められると、何が入っているか聞いてから口をつける。感想だけは遠慮なく言う。', ''),
    ('129', '147', '担当を通じて協力する同僚', 'パラム', '最初は強がるが、世話を焼かれると素直になる。', '休日の午後に食堂で捕まり、軽食を食べながら近況を話す。気が緩むともう一皿頼む。', ''),
    ('129', '148', '担当を通じて協力する同僚', 'ルア', '明るい勢いに乗り、冗談半分で張り合う。', 'ルアの新しい曲を先に聞いて感想を言うことがある。ミカドに誰が一番印象を残すかで話が盛り上がる。', ''),
    ('129', '149', '担当を通じて協力する同僚', 'クイナ', '呆れたふりでからかうが、無理に追い立てない。', '昼寝中のクイナを見つけると、声をかけるだけかけて隣の窓辺で休む。二人とも動き出すまで時間がかかる。', ''),
    ('129', '150', '担当を通じて協力する同僚', 'ソルベ', '張り切りぶりを気に入り、同じくらい大きな声で返す。', '休日でも走りに誘われれば乗る。終わった後の朝食まで付き合って、どちらが多く食べるか競うこともある。', ''),
    ('129', '151', '担当を通じて協力する同僚', 'ルミ', 'からかわれるとすぐに言い返し、あとに引きずらない。', 'ミカドの前で何を着るか聞かれ、気づけば服選びに付き合ってもらっていることがある。', ''),
    ('129', '152', '担当を通じて協力する同僚', 'シノ', 'いやみに聞こえる言葉も勢いで受け流すが、恋の話では引かない。', 'ミカドへの気持ちではライバル。廊下で顔を合わせるたび、笑顔のまま互いの様子を探ることがある。', ''),
    ('129', '153', '担当を通じて協力する同僚', 'メディ', '堅い受け答えにも気取らず、失敗は笑って流す。', 'お茶を出してもらうついでにミカドの近況を聞こうとする。メディがとぼけると、次の休憩でも同じ話を振る。', ''),
    ('129', '154', '担当を通じて協力する同僚', 'セナ', '気楽に声をかけ、疲れているときには押しつけない。', '夜更けまで起きているセナに温かい飲み物を持っていくことがある。長話をせず一緒に一息つく。', ''),
    ('129', '155', '担当を通じて協力する同僚', 'ケト', '心配されると強がるが、穏やかに言われると折れる。', '休日に顔を出すと、近況を話すつもりが寝不足まで見抜かれる。茶を飲んでから帰るのがお決まり。', ''),
    ('129', '156', '担当を通じて協力する同僚', 'ワイズ', '堅い物言いを軽口で受け止め、怒らせない程度にからかう。', 'ミカドに本を贈ろうと思ったときだけ妙に真剣に相談する。贈り主のことを聞かれると誤魔化す。', ''),
    ('129', '157', '親友・飲み仲間', 'シズ', '肩書きを離れて遠慮なく笑い合う。', '親友で飲み仲間。休みが合う夜は一杯やり、普段は言えない愚痴も互いに笑い飛ばす。', ''),
    ('129', '158', '担当を通じて協力する同僚', 'シュミール', '姉貴分のように可愛がり、頼まれれば気前よく付き合う。', '休日に作った小物を見せられると身につけて感想を言う。酒が苦手なので、二人で休むときは別の飲み物を用意する。', ''),
    ('129', '159', '担当を通じて協力する同僚', 'ミゼル', '災難の話を面白がりつつ、落ち込んでいないか気にかける。', '食堂で居合わせると不運話を肴に笑う。ミゼルの妙に前向きなオチに、先に笑い出すのはホムラのほう。', ''),
    ('129', '160', '担当を通じて協力する同僚', 'アヤメ', '悪ふざけを大らかに受けるが、度が過ぎたときはきっぱり止める。', '廊下で仕掛けられたいたずらに気づくと、わざと引っかかったふりをすることがある。ばらした後は二人で笑う。', ''),
    ('130', '129', '八星剣の同僚', 'ホムラ', '穏やかで聞き上手。', '休みが重なれば、食堂の長卓で飲み物を手に、最近おかしかった話を聞かせる。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '131', '八星剣の同僚', 'フウ', '穏やかで聞き上手。', '休みが重なれば、晴れた休日に中庭で追いかけっこをして、先に疲れた方が飲み物を買う。相手に合わせて話題を変え、聞いた悩みは外で話さない。', '八星剣の幹部同士。'),
    ('130', '132', '八星剣の同僚', 'ライ', '穏やかで聞き上手。', '休みが重なれば、夜更けにゲームで遊び、負けたほうが次の対戦をしつこく求める。相手に合わせて話題を変え、聞いた悩みは外で話さない。', '八星剣の幹部同士。'),
    ('130', '133', '八星剣の同僚', 'チカ', '穏やかで聞き上手。', '休みが重なれば、休日の早朝に散歩し、帰りに売店の温かい飲み物を買う。相手に合わせて話題を変え、聞いた悩みは外で話さない。', '八星剣の幹部同士。'),
    ('130', '134', '八星剣の同僚', 'ユキ', '穏やかで聞き上手。', '休みが重なれば、中庭に来る小動物を眺めながら、会話の少ない時間を一緒に過ごす。相手に合わせて話題を変え、聞いた悩みは外で話さない。', '八星剣の幹部同士。'),
    ('130', '135', '八星剣の同僚', 'ヒカリ', '穏やかで聞き上手。', '休みが重なれば、疲れた日に庭のベンチでお茶を飲み、落ち着くまで話を聞き合う。相手に合わせて話題を変え、聞いた悩みは外で話さない。', '八星剣の幹部同士。'),
    ('130', '136', '八星剣の同僚', 'ヤミ', '穏やかで聞き上手。', '休みが重なれば、夜の回廊で顔を合わせると、短く話してから別々に帰る。相手に合わせて話題を変え、聞いた悩みは外で話さない。', '八星剣の幹部同士。'),
    ('130', '141', 'ミカドの妹・業務で会う相手', 'ミコトさん', '穏やかで聞き上手。兄の話題では牽制を受けやすく、距離を測りながら話す。', '休みにたまたま顔を合わせると、ミカドが何を好むか探り合う。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '145', '担当を通じて協力する同僚', 'シュカさん', '穏やかで聞き上手。', '休みが重なれば、休み前の晩にチェス盤を挟み、負けた方が茶を淹れる。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '146', '同じ軍団の副官', 'セイラ', '穏やかで聞き上手。', '休みが重なれば、食堂で珍しい味の飲み物を見かけると感想を聞き、あとで自分も試す。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '147', '担当を通じて協力する同僚', 'パラムさん', '穏やかで聞き上手。', '休みが重なれば、休日の昼に甘いものを持ち寄り、気が抜けるまでゆっくり休む。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '148', '担当を通じて協力する同僚', 'ルアさん', '穏やかで聞き上手。', '休みが重なれば、休みの日に衣装や曲を見せ合い、即席の観客役を頼む。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '149', '担当を通じて協力する同僚', 'クイナさん', '穏やかで聞き上手。', '休みが重なれば、昼寝できる窓辺で鉢合わせし、空いている側を譲り合う。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '150', '担当を通じて協力する同僚', 'ソルベさん', '穏やかで聞き上手。', '休みが重なれば、休日でも軽い運動に誘い、帰りには大盛りの朝食を楽しむ。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '151', '担当を通じて協力する同僚', 'ルミさん', '穏やかで聞き上手。', '休みが重なれば、休みの日に髪や服をいじらせてもらい、似合う色を遠慮なく言う。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '152', '担当を通じて協力する同僚', 'シノさん', '穏やかで聞き上手。', '休みが重なれば、雨の日の回廊で立ち話をして、互いにどこまで本気か曖昧なまま別れる。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '153', '担当を通じて協力する同僚', 'メディさん', '穏やかで聞き上手。', '休みが重なれば、休憩時にお茶を淹れてもらい、菓子皿が落ちそうならそっと押さえる。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '154', '担当を通じて協力する同僚', 'セナさん', '穏やかで聞き上手。', '休みが重なれば、遅い時間に温かい飲み物を差し入れ、疲れていれば長居せず引き上げる。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '155', '担当を通じて協力する同僚', 'ケトさん', '穏やかで聞き上手。', '休みが重なれば、温かい飲み物をもらい、最近ちゃんと眠れているか聞かれる。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '156', '担当を通じて協力する同僚', 'ワイズさん', '穏やかで聞き上手。', '休みが重なれば、休館前の静かな書庫で本の感想を交わし、続きは別の日に持ち越す。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '157', '担当を通じて協力する同僚', 'シズさん', '穏やかで聞き上手。', '休みが重なれば、日が落ちると聖堂の外で一杯付き合い、話が脱線するまま夜更けまで過ごす。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '158', '担当を通じて協力する同僚', 'シュミールさん', '穏やかで聞き上手。', '休みが重なれば、休憩中に手作りの小物を見せてもらい、気に入ったら使い道を一緒に考える。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '159', '担当を通じて協力する同僚', 'ミゼルさん', '穏やかで聞き上手。', '休みが重なれば、食堂で居合わせると、最近の不運を本人が笑い話にして聞かせる。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('130', '160', '担当を通じて協力する同僚', 'アヤメさん', '穏やかで聞き上手。', '休みが重なれば、廊下で小さないたずらを仕掛けられ、仕返しする機会をうかがう。相手に合わせて話題を変え、聞いた悩みは外で話さない。', ''),
    ('131', '129', '八星剣の同僚', 'ホムラ姉', '距離が近く、屈託なく誘う。', '休みが重なれば、食堂の長卓で飲み物を手に、最近おかしかった話を聞かせる。気に入ると次の休みにも相手を誘いに行く。', ''),
    ('131', '130', '八星剣の同僚', 'スイ姉', '距離が近く、屈託なく誘う。', '休みが重なれば、書庫の窓辺で本を交換し、お気に入りの箇所を教え合う。気に入ると次の休みにも相手を誘いに行く。', ''),
    ('131', '132', '八星剣の同僚', 'ライ姉', '距離が近く、屈託なく誘う。', '休みが重なれば、夜更けにゲームで遊び、負けたほうが次の対戦をしつこく求める。気に入ると次の休みにも相手を誘いに行く。', '八星剣の幹部同士。'),
    ('131', '133', '八星剣の同僚', 'チカ姉', '距離が近く、屈託なく誘う。', '休みが重なれば、休日の早朝に散歩し、帰りに売店の温かい飲み物を買う。気に入ると次の休みにも相手を誘いに行く。', '八星剣の幹部同士。'),
    ('131', '134', '八星剣の同僚', 'ユキ姉', '距離が近く、屈託なく誘う。', '休みが重なれば、中庭に来る小動物を眺めながら、会話の少ない時間を一緒に過ごす。気に入ると次の休みにも相手を誘いに行く。', '八星剣の幹部同士。'),
    ('131', '135', '八星剣の同僚', 'ヒカリ姉', '距離が近く、屈託なく誘う。', '休みが重なれば、疲れた日に庭のベンチでお茶を飲み、落ち着くまで話を聞き合う。気に入ると次の休みにも相手を誘いに行く。', '八星剣の幹部同士。'),
    ('131', '136', '八星剣の同僚', 'ヤミ姉', '距離が近く、屈託なく誘う。', '休みが重なれば、夜の回廊で顔を合わせると、短く話してから別々に帰る。気に入ると次の休みにも相手を誘いに行く。', '八星剣の幹部同士。'),
    ('131', '141', 'ミカドの妹・業務で会う相手', 'ミコト', '距離が近く、屈託なく誘う。兄の話題では牽制を受けやすく、距離を測りながら話す。', '休みにたまたま顔を合わせると、ミカドが何を好むか探り合う。気に入ると次の休みにも相手を誘いに行く。', ''),
    ('131', '145', '担当を通じて協力する同僚', 'シュカ', '距離が近く、屈託なく誘う。', '休みが重なれば、休み前の晩にチェス盤を挟み、負けた方が茶を淹れる。気に入ると次の休みにも相手を誘いに行く。', ''),
    ('131', '146', '担当を通じて協力する同僚', 'セイラ', '距離が近く、屈託なく誘う。', '休みが重なれば、食堂で珍しい味の飲み物を見かけると感想を聞き、あとで自分も試す。気に入ると次の休みにも相手を誘いに行く。', ''),
    ('131', '147', '頼れる副官', 'パラム', '甘えやすく、嬉しいことは真っ先に話す。', '休み時間におやつをもらい、そのまま寝落ちすることもある。パラムのそばでは肩の力が抜ける。', ''),
    ('131', '148', '担当を通じて協力する同僚', 'ルア', '距離が近く、屈託なく誘う。', '休みが重なれば、休みの日に衣装や曲を見せ合い、即席の観客役を頼む。気に入ると次の休みにも相手を誘いに行く。', ''),
